#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> v = {5, 2, 9, 1, 5, 6};
    sort(v.begin(), v.end());                        // 1 2 5 5 6 9
    sort(v.begin(), v.end(), greater<int>());        // 9 6 5 5 2 1
    sort(v.rbegin(), v.rend());                      // też malejąco

    int t[] = {4, 3, 8, 1};
    sort(t, t + 4);                                  // zwykła tablica: wskaźniki

    vector<pair<int, int>> p = {{2, 5}, {1, 9}, {2, 1}};
    sort(p.begin(), p.end());                        // (1,9) (2,1) (2,5)

    // po wartości bezwzględnej, przy remisie rosnąco
    vector<int> w = {-3, 2, -1, 3, 1};
    sort(w.begin(), w.end(), [](int a, int b) {
        if (abs(a) != abs(b)) return abs(a) < abs(b);
        return a < b;
    });
    for (int x : w) cout << x << ' ';                // -1 1 2 -3 3
    cout << '\n';
}

struct Uczen {
    string imie;
    int punkty;
    int czas;
};
// punkty malejąco, potem czas rosnąco, potem imię alfabetycznie
bool lepszy(const Uczen& a, const Uczen& b) {
    if (a.punkty != b.punkty) return a.punkty > b.punkty;
    if (a.czas != b.czas) return a.czas < b.czas;
    return a.imie < b.imie;
}
void posortuj(vector<Uczen>& v) {
    sort(v.begin(), v.end(), lepszy);
}

