#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<long long> a = {3, 1, 4, 1, 5, 9};
    int n = a.size();
    vector<long long> p(n + 1, 0);                    // p[i] = suma a[0..i-1]
    partial_sum(a.begin(), a.end(), p.begin() + 1);
    // suma a[l..r] (włącznie, indeksy od 0) = p[r+1] - p[l]
    int l = 1, r = 4;
    cout << p[r + 1] - p[l] << '\n';                  // 1+4+1+5 = 11

    vector<long long> d(n);
    adjacent_difference(a.begin(), a.end(), d.begin());   // d[0]=a[0], d[i]=a[i]-a[i-1]
    for (auto x : d) cout << x << ' ';                // 3 -2 3 -3 4 4
    cout << '\n';

    partial_sum(d.begin(), d.end(), d.begin());       // sumy prefiksowe różnic = oryginał
    cout << (d == a) << '\n';                         // 1
}

#include <bits/stdc++.h>
