// q operacji "dodaj v do a[l..r]" offline, potem wypisz tablicę — O(n + q)
int main() {
    int n = 6;
    vector<long long> diff(n + 1, 0);
    vector<array<int, 3>> ops = {{0, 2, 5}, {1, 4, 2}, {3, 5, 1}};   // (l, r, v)
    for (auto [l, r, v] : ops) {
        diff[l] += v;
        diff[r + 1] -= v;
    }
    vector<long long> a(n);
    partial_sum(diff.begin(), diff.begin() + n, a.begin());
    for (auto x : a) cout << x << ' ';     // 5 7 7 3 3 1
    cout << '\n';
}

